#!/usr/bin/env python3
"""RF2 Phase B: SB1R-QA / QB outline variant (2026-10-29). The baseline boards carry a 2 mm locating tab to r 116, which cannot sit inside the RF2 head's
2 mm wall at D233. This runs a patched COPY of src/pcb/sbq_export.py (baseline untouched) whose only changes are the outline (a full r 114 circle) and, since 2026-10-31,
a 4th NPTH hole (3.4 mm, the M3 tool) at the PRX feed (r 72, 135 deg: the copper-free window of both boards) for the planar RX leads.
Checks: copper of every layer identical to the baseline Gerbers (geometry, src/pcb/gerber_geom.py: symmetric difference area), outline radius <= 114.0,
KiCad DRC with the baseline SB1R rules (src/pcb/kicad_drc.py). Outputs: out/SB1R_RF2/, sb1r_variant_check.json.
usage (repo root; inputs in data/reference: the baseline SB1R geometry and Gerbers): python3 rf2/head/rf2_sb1r_variant.py"""
import os, sys, json, subprocess, glob, math
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.abspath(os.path.join(HERE, "..", "..")); OUT = os.path.join(HERE, "out", "SB1R_RF2")
os.makedirs(OUT, exist_ok=True); sys.path.insert(0, HERE)
src = open(os.path.join(ROOT, "src/pcb/sbq_export.py")).read()
def patch(s, a, b, what):
    assert s.count(a) == 1, f"patch target not unique: {what}"; return s.replace(a, b)
s = patch(src, "    return pts+[(116.0,-2.0),(116.0,2.0),pts[0]]", "    a=np.linspace(0,2*math.pi,721)[:-1]; pts=[(RB*math.cos(x),RB*math.sin(x)) for x in a]; return pts+[pts[0]]   # RF2: no tab", "outline")
s = patch(s, 'os.makedirs("kit_v22/KICAD_SBQ",exist_ok=True)', f'os.makedirs({OUT!r},exist_ok=True)', "dir")
s = patch(s, 'kicad("SB1R-QA","QA_COIL",0.0,"kit_v22/KICAD_SBQ/SB1R-QA.kicad_pcb"); kicad("SB1R-QB","QB_COIL",45.0,"kit_v22/KICAD_SBQ/SB1R-QB.kicad_pcb")',
          f'kicad("SB1R-QA","QA_COIL",0.0,{os.path.join(OUT, "SB1R-QA-RF2.kicad_pcb")!r}); kicad("SB1R-QB","QB_COIL",45.0,{os.path.join(OUT, "SB1R-QB-RF2.kicad_pcb")!r})', "kicad paths")
s = patch(s, 'gerber("SB1R-QA",0.0,"kit_v22/GERBER_SB1R_QA"); gerber("SB1R-QB",45.0,"kit_v22/GERBER_SB1R_QB")',
          f'gerber("SB1R-QA",0.0,{os.path.join(OUT, "GERBER_QA")!r}); gerber("SB1R-QB",45.0,{os.path.join(OUT, "GERBER_QB")!r}); import sys; sys.exit(0)', "gerber paths (stop before the figures)")
s = patch(s, 'G=json.load(open("kit_v22/sbq_geometry.json"))', f'G=json.load(open({os.path.join(ROOT, "data/reference/sbq_geometry.json")!r}))', "geometry input (AXE2: data/reference)")
import rf2_prx as PRX                                                                    # owner 2026-10-31 (hybrid receive): the PRX leads rise through a 3.4 mm NPTH feed hole
_fx, _fy = PRX.FEED["r"] * math.cos(math.radians(PRX.FEED["deg"])), PRX.FEED["r"] * math.sin(math.radians(PRX.FEED["deg"])); assert abs(PRX.FEED["hole_d"] - 3.4) < 1e-9   # same M3 drill tool (T1C3.400)
s = patch(s, "for a in HA]; return L,vias,pads,holes", f"for a in HA]+[({_fx:.4f},{_fy:.4f})]; return L,vias,pads,holes   # RF2: PRX feed hole (r 72, 135 deg) in QA and QB", "PRX feed hole")
s = '"""RF2 COPY of src/pcb/sbq_export.py, generated by rf2_sb1r_variant.py: outline without the r 116 tab. Do not edit."""\n' + s
open(os.path.join(OUT, "sbq_export_rf2.py"), "w").write(s)
r = subprocess.run([sys.executable, os.path.join(OUT, "sbq_export_rf2.py")], cwd=OUT, capture_output=True, text=True, env=dict(os.environ, PYTHONPATH=os.path.join(ROOT, "src/pcb")))
res = dict(status="RF2 SB1R outline variant (copper from the baseline generator, outline changed only)", export_rc=r.returncode, export_err=r.stderr[-300:])
sys.path.insert(0, os.path.join(ROOT, "src/pcb")); import gerber_geom as GG
cmp = {}
for B, base_dir, new_dir in (("SB1R-QA", "data/reference/GERBER_SB1R_QA", "GERBER_QA"), ("SB1R-QB", "data/reference/GERBER_SB1R_QB", "GERBER_QB")):
    for f in sorted(glob.glob(os.path.join(ROOT, base_dir, "*"))):
        n = os.path.basename(f)
        if not n.lower().endswith((".gbr", ".gtl", ".gbl", ".g1", ".g2")) or "edge" in n.lower() or "cu" not in n.lower() and "copper" not in n.lower(): continue
        g0 = GG.layer_geometry(f)[0]; g1 = GG.layer_geometry(os.path.join(OUT, new_dir, n))[0]          # (geometry, primitive count)
        cmp[f"{B} {n}"] = dict(area_mm2=round(g0.area, 3), sym_diff_mm2=round(g0.symmetric_difference(g1).area, 6))
res["copper_identical"] = dict(layers=cmp, ok=bool(cmp) and all(v["sym_diff_mm2"] < 1e-3 for v in cmp.values()))
import pcbnew
rmax = {}
for B in ("SB1R-QA", "SB1R-QB"):
    b = pcbnew.LoadBoard(os.path.join(OUT, f"{B}-RF2.kicad_pcb")); bb = b.GetBoardEdgesBoundingBox(); rmax[B] = round(pcbnew.ToMM(bb.GetWidth()) / 2 - 0.05, 3)    # the edge box includes half the 0.1 mm Edge.Cuts line
res["outline_radius_mm"] = dict(values=rmax, ok=all(v <= 114.0 + 1e-3 for v in rmax.values()))
drc = {}
for B in ("SB1R-QA", "SB1R-QB"):
    out = os.path.join(OUT, f"kicad_drc_{B}.json")
    subprocess.run([sys.executable, os.path.join(ROOT, "src/pcb/kicad_drc.py"), os.path.join(OUT, f"{B}-RF2.kicad_pcb"), out, B], capture_output=True, text=True, cwd=ROOT)
    d = json.load(open(out)); drc[B] = dict(errors=d.get("errors"), unconnected=d.get("unconnected"))
res["kicad_drc"] = dict(boards=drc, ok=all(v["errors"] == {} and v["unconnected"] == 0 for v in drc.values()))
res["ok"] = res["export_rc"] == 0 and res["copper_identical"]["ok"] and res["outline_radius_mm"]["ok"] and res["kicad_drc"]["ok"]
json.dump(res, open(os.path.join(OUT, "sb1r_variant_check.json"), "w"), indent=1); print(json.dumps(res, indent=1)[:2500])
